{
  "findings": [
    {
      "check_id": "AVD-AWS-0130",
      "title": "IMDS access without token requirement",
      "resource": "aws_launch_template.web_app",
      "severity": "HIGH",
      "explanation": "Instance metadata service can be interacted with freely, potentially allowing unauthorized access to instance metadata."
    },
    {
      "check_id": "CKV_AWS_8",
      "title": "Unencrypted Elastic Blocks Store",
      "resource": "aws_launch_template.web_app",
      "severity": "MEDIUM",
      "explanation": "Data stored in the instance Elastic Blocks Store is not securely encrypted."
    },
    {
      "check_id": "AVD-AWS-SECRET-1", 
      "title": "Hardcoded secret in user data",
      "resource": "aws_launch_template.web_app",
      "severity": "CRITICAL",
      "explanation": "The API key 'sk-1234567890abcdef' is hardcoded in the user data, potentially exposing sensitive information."
    }
  ],
  "patched_code": "resource "aws_launch_template" "web_app" {
  name_prefix   = "automated-employee-onboarding-platform-lt-web-"
  image_id      = data.aws_ami.ubuntu.id
  instance_type = var.instance_type
  key_name      = var.key_pair_name
  vpc_security_group_ids = [aws_security_group.web_app.id]
  user_data = base64encode(<<-EOF
              export DATABASE_PASSWORD="${var.db_password}"
              export API_KEY="${var.api_key}"
              apt-get update
              apt-get install -y nginx nodejs npm
              systemctl start nginx
              systemctl enable nginx
              EOF
  )
  tag_specifications {
    resource_type = "instance"
  }
  metadata_options {
    http_tokens = "required"
  }
  block_device_mappings {
    device_name = "/dev/sda1"
    ebs {
      encrypted = true
    }
  }
}",
  "fix_summary": "Enabled IMDS token requirement, encrypted EBS volume, and removed hardcoded API key from user data."
}
